#!/usr/bin/env python3
"""Build docs/*.md into the static website. Requires docs-requirements.txt."""
from __future__ import annotations

import argparse
from dataclasses import dataclass
from html import escape
import json
from pathlib import Path
import posixpath
import re
import shutil
import sys
import tempfile
from urllib.parse import quote, unquote, urlsplit, urlunsplit

from markdown_it import MarkdownIt
from markdown_it.token import Token
from pygments import highlight
from pygments.formatters import HtmlFormatter
from pygments.lexers import get_lexer_by_name
from pygments.style import Style
from pygments.token import (
    Comment,
    Error,
    Generic,
    Keyword,
    Literal,
    Name,
    Number,
    Operator,
    Punctuation,
    String,
    Text,
)
from pygments.util import ClassNotFound

ROOT = Path(__file__).resolve().parents[2]
# Keep the marker stable so previous generated builds remain replaceable.
MARKER = "Generated by tools/compile_docs.py. Edit the Markdown sources instead.\n"


class LandingDarkStyle(Style):
    """Syntax theme matching the landing page near-black, cyan, and violet palette."""

    background_color = "#090c0f"
    styles = {
        Text: "#e4e8ec",
        Punctuation: "#e4e8ec",
        Comment: "italic #8a959e",
        Comment.Hashbang: "italic #8a959e",
        Comment.Multiline: "italic #8a959e",
        Comment.Preproc: "italic #8a959e",
        Comment.PreprocFile: "italic #8a959e",
        Comment.Single: "italic #8a959e",
        Comment.Special: "italic #8a959e",
        Keyword: "bold #bba0ff",
        Keyword.Constant: "#86ddeb",
        Keyword.Declaration: "bold #bba0ff",
        Keyword.Namespace: "bold #bba0ff",
        Keyword.Pseudo: "#bba0ff",
        Keyword.Reserved: "bold #bba0ff",
        Keyword.Type: "#86ddeb",
        Name.Attribute: "#86ddeb",
        Name.Builtin: "#22d3ee",
        Name.Builtin.Pseudo: "#22d3ee",
        Name.Class: "bold #22d3ee",
        Name.Constant: "#86ddeb",
        Name.Decorator: "#bba0ff",
        Name.Entity: "#bba0ff",
        Name.Exception: "bold #22d3ee",
        Name.Function: "#22d3ee",
        Name.Function.Magic: "#22d3ee",
        Name.Label: "#bba0ff",
        Name.Namespace: "#22d3ee",
        Name.Tag: "bold #22d3ee",
        Name.Variable: "#e4e8ec",
        Literal.Number: "#bba0ff",
        Literal.String: "#d0bfff",
        Literal.String.Affix: "#bba0ff",
        Literal.String.Backtick: "#d0bfff",
        Literal.String.Char: "#d0bfff",
        Literal.String.Doc: "italic #8a959e",
        Literal.String.Double: "#d0bfff",
        Literal.String.Escape: "#86ddeb",
        Literal.String.Heredoc: "#d0bfff",
        Literal.String.Interpol: "#86ddeb",
        Literal.String.Other: "#d0bfff",
        Literal.String.Regex: "#86ddeb",
        Literal.String.Single: "#d0bfff",
        Literal.String.Symbol: "#86ddeb",
        Operator: "#86ddeb",
        Operator.Word: "bold #bba0ff",
        Generic.Heading: "bold #22d3ee",
        Generic.Subheading: "bold #bba0ff",
        Generic.Deleted: "#f87171",
        Generic.Inserted: "#4ade80",
        Generic.Error: "#f87171",
        Generic.Prompt: "#8a959e",
        Generic.Output: "#8a959e",
        Generic.Traceback: "#f87171",
        Error: "#f87171",
    }


@dataclass
class Page:
    source: Path
    output: Path
    title: str
    tokens: list[Token]
    headings: list[tuple[int, str, str]]


def plain(token: Token) -> str:
    """Text used in heading IDs, navigation, and search, without HTML markup."""
    if token.children:
        return "".join(plain(child) for child in token.children)
    return token.content if token.type not in {"html_inline", "html_block"} else ""


def slug(text: str) -> str:
    return re.sub(r"[^\w\- ]", "", text.lower()).replace(" ", "-") or "section"


def code_highlight(code: str, language: str, _attrs: str) -> str:
    # Rust documentation fences may use comma-separated annotations.
    try:
        lexer = get_lexer_by_name(language.split(",")[0])
    except ClassNotFound:
        return escape(code)
    return highlight(code, lexer, HtmlFormatter(nowrap=True))


def parser() -> MarkdownIt:
    md = MarkdownIt("js-default", {"html": False, "highlight": code_highlight})

    def fence(tokens, index, options, env):
        token = tokens[index]
        language = token.info.strip().split(maxsplit=1)[0] if token.info.strip() else "text"
        language = language.split(",")[0]
        label = {"bash": "Terminal", "sh": "Terminal", "shell": "Terminal",
                 "python": "Python", "rust": "Rust", "json": "JSON"}.get(language, language)
        return (f'<div class="code-block"><div class="code-heading"><span>{escape(label)}</span></div>'
                f'<pre><code class="language-{escape(language, quote=True)}">'
                f'{code_highlight(token.content, language, "")}</code></pre></div>\n')

    def table_open(tokens, index, options, env):
        return '<div class="table-scroll" role="region" aria-label="Data table" tabindex="0"><table>\n'

    def table_close(tokens, index, options, env):
        return '</table></div>\n'

    md.renderer.rules["fence"] = fence
    md.renderer.rules["table_open"] = table_open
    md.renderer.rules["table_close"] = table_close
    return md


def read_pages(source: Path, md: MarkdownIt) -> list[Page]:
    pages = []
    outputs: set[Path] = set()
    for path in sorted(source.rglob("*.md")):
        if not path.resolve().is_relative_to(source):
            raise ValueError(f"Document escapes source directory: {path}")
        relative = path.relative_to(source)
        output = relative.with_name("index.html") if path.name == "README.md" else relative.with_suffix(".html")
        if output in outputs:
            raise ValueError(f"Duplicate HTML destination: {output}")
        outputs.add(output)
        tokens = md.parse(path.read_text(encoding="utf-8"))
        used: set[str] = set()
        headings = []
        title = path.stem.replace("-", " ").capitalize()
        for i, token in enumerate(tokens):
            if token.type != "heading_open":
                continue
            text = plain(tokens[i + 1])
            base = slug(text)
            anchor = base
            suffix = 0
            while anchor in used:
                suffix += 1
                anchor = f"{base}-{suffix}"
            used.add(anchor)
            token.attrSet("id", anchor)
            headings.append((int(token.tag[1:]), text, anchor))
            if token.tag == "h1" and not any(level == 1 for level, _, _ in headings[:-1]):
                title = text
        pages.append(Page(path.resolve(), output, title, tokens, headings))
    if not pages or not any(p.output == Path("index.html") for p in pages):
        raise ValueError("The documentation source must contain README.md (or index.md).")
    return pages


def relative_url(destination: Path, current: Path) -> str:
    return quote(posixpath.relpath(destination.as_posix(), current.parent.as_posix()), safe="/.-_")


def rewrite_link(url: str, page: Page, pages: dict[Path, Page], root: Path,
                 repository: str, assets: dict[Path, Path], image: bool = False) -> str:
    parts = urlsplit(url)
    if parts.scheme or parts.netloc:
        return url
    target = (page.source.parent / unquote(parts.path)).resolve() if parts.path else page.source
    linked_page = pages.get(target)
    if linked_page:
        if parts.fragment and unquote(parts.fragment) not in {h[2] for h in linked_page.headings}:
            raise ValueError(f"{page.source}: missing heading in {url!r}")
        path = relative_url(linked_page.output, page.output) if parts.path else ""
        return urlunsplit(("", "", path, parts.query, parts.fragment))
    if not target.exists() or not target.is_relative_to(root):
        raise ValueError(f"{page.source}: missing or out-of-repository link {url!r}")
    repo_path = target.relative_to(root)
    if image:
        if not target.is_file():
            raise ValueError(f"{page.source}: image is not a file: {url!r}")
        destination = Path("_assets") / repo_path
        assets[destination] = target
        return urlunsplit(("", "", relative_url(destination, page.output), parts.query, parts.fragment))
    kind = "tree" if target.is_dir() else "blob"
    path = f"{repository}/{kind}/main/{quote(repo_path.as_posix(), safe='/')}"
    return path + ("?" + parts.query if parts.query else "") + ("#" + parts.fragment if parts.fragment else "")


def rewrite_tokens(page: Page, pages: dict[Path, Page], root: Path,
                   repository: str, assets: dict[Path, Path]) -> None:
    def visit(tokens: list[Token]) -> None:
        for token in tokens:
            attribute = "href" if token.type == "link_open" else "src" if token.type == "image" else None
            if attribute:
                url = token.attrGet(attribute)
                if url is not None:
                    token.attrSet(attribute, rewrite_link(url, page, pages, root, repository, assets, token.type == "image"))
            if token.children:
                visit(token.children)
    visit(page.tokens)


def page_order(pages: list[Page]) -> list[Page]:
    """Use the docs index's link order, then include any new or nested guides."""
    first = next(p for p in pages if p.output == Path("index.html"))
    by_source = {p.source: p for p in pages}
    ordered = [first]
    for token in first.tokens:
        for child in token.children or []:
            if child.type == "link_open":
                parts = urlsplit(child.attrGet("href") or "")
                if not parts.scheme and parts.path:
                    linked = by_source.get((first.source.parent / unquote(parts.path)).resolve())
                    if linked and linked not in ordered:
                        ordered.append(linked)
    return ordered + [p for p in pages if p not in ordered]


def search_entries(page: Page) -> list[dict[str, str]]:
    records = []
    text: list[str] = []
    heading = page.title
    anchor = ""
    def flush() -> None:
        if text:
            records.append({"title": page.title, "heading": heading,
                            "url": page.output.as_posix() + ("#" + anchor if anchor else ""),
                            "text": " ".join(text)})
    for i, token in enumerate(page.tokens):
        if token.type == "heading_open":
            flush()
            text = []
            heading = plain(page.tokens[i + 1])
            anchor = token.attrGet("id") or ""
        elif token.type in {"inline", "fence", "code_block"}:
            text.append(plain(token))
    flush()
    return records


def render_shell(page: Page, pages: list[Page], body: str, repository: str, base_url: str) -> str:
    def href(path: str) -> str:
        return escape(relative_url(Path(path), page.output), quote=True)
    docs_root = posixpath.relpath(".", page.output.parent.as_posix()) + "/"
    home = posixpath.relpath("..", page.output.parent.as_posix()) + "/"
    groups: dict[str, list[Page]] = {}
    labels = {"guides": "Getting started", "solver": "The solver", "reference": "Reference",
              "extensions": "Extensions", "benchmarks": "Benchmarks", "internal": "Internals",
              "pybaldes": "PyBaldes · Python"}
    for guide in pages:
        section = guide.output.parts[0] if len(guide.output.parts) > 1 else "overview"
        groups.setdefault(section, []).append(guide)
    navigation = ""
    for section, guides in groups.items():
        links = "".join(
            f'<a href="{href(p.output.as_posix())}"' + (' aria-current="page"' if p is page else '')
            + f'>{escape("Overview" if p.output == Path("index.html") else p.title)}</a>' for p in guides
        )
        navigation += (f'<div class="nav-group"><p class="nav-group-title">'
                       f'{escape(labels.get(section, section.capitalize()))}</p>{links}</div>')
    toc = "".join(f'<a class="toc-level-{level}" href="#{escape(anchor)}">{escape(title)}</a>'
                  for level, title, anchor in page.headings if level in {2, 3})
    section = page.output.parts[0] if len(page.output.parts) > 1 else "overview"
    section_label = labels.get(section, section.capitalize())
    index = pages.index(page)
    previous = pages[index - 1] if index else None
    following = pages[index + 1] if index + 1 < len(pages) else None
    adjacent = "".join(f'<a href="{href(p.output.as_posix())}"><small>{direction}</small>{escape(p.title)} <span aria-hidden="true">↗</span></a>'
                       for p, direction in [(previous, "Previous guide"), (following, "Next guide")] if p)
    canonical = escape(base_url.rstrip("/") + "/docs/" + page.output.as_posix(), quote=True)
    edit_url = repository + "/blob/main/" + quote(page.source.relative_to(ROOT).as_posix(), safe="/") if page.source.is_relative_to(ROOT) else repository
    description = " ".join(plain(t) for t in page.tokens if t.type == "inline")[:180]
    return f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{escape(description, quote=True)}">
<meta name="theme-color" content="#0b0e11">
<title>{escape(page.title)} — BALDES docs</title>
<link rel="canonical" href="{canonical}">
<link rel="icon" href="{href('_static/mark.svg')}" type="image/svg+xml">
<link rel="stylesheet" href="{href('_static/site.css')}">
<link rel="stylesheet" href="{href('_static/docs.css')}">
<link rel="stylesheet" href="{href('_static/syntax.css')}">
<script src="{href('_static/app.js')}" defer></script>
<script src="{href('_static/docs.js')}" defer></script>
</head>
<body class="landing-dark docs-body" data-docs-root="{escape(docs_root)}">
<a class="skip-link" href="#content">Skip to content</a>
<header class="site-header docs-header"><a class="brand" href="{escape(home)}"><img src="{href('_static/mark.svg')}" width="32" height="40" alt="">BALDES <span class="version">2.0</span></a>
<nav aria-label="Main"><a href="{escape(home)}">Home</a><a href="{href('index.html')}" aria-current="true">Documentation</a><a href="{escape(repository)}">GitHub ↗</a></nav></header>
<div class="docs-layout">
<aside class="docs-sidebar">
<details class="guide-menu" open><summary>Documentation</summary><nav aria-label="Guides">{navigation}</nav></details>
<a class="source-link" href="{escape(edit_url)}">View Markdown source ↗</a>
</aside>
<main id="content" class="doc-main" tabindex="-1">
<div class="doc-toolbar"><span class="eyebrow">DOCS <span aria-hidden="true">/</span> {escape(section_label)}</span><form class="doc-search" role="search" action="{href('index.html')}" method="get"><label for="docs-search">Search guides</label><input id="docs-search" type="search" name="q" placeholder="Search guides…" autocomplete="off" aria-controls="search-results"><span class="search-shortcut" aria-hidden="true">⌘ K / Ctrl K</span><span id="search-status" class="sr-only" role="status"></span></form></div>
<section id="search-results" class="search-results" aria-label="Search results" hidden></section>
<noscript><p class="notice">Browse the guides with the navigation. Search needs JavaScript.</p></noscript>
<article class="prose">{body}</article>
<nav class="page-turn" aria-label="Adjacent guides">{adjacent}</nav>
<footer class="doc-footer">BALDES · Rust tools for vehicle routing · <a href="{escape(repository)}/blob/main/LICENSE">MIT license</a></footer>
</main>
<aside class="doc-toc"><nav aria-label="On this page"><p class="eyebrow">ON THIS PAGE</p>{toc}</nav></aside>
</div>
</body></html>'''


def build(source: Path, output: Path, root: Path = ROOT,
          repository: str = "https://github.com/lseman/baldes",
          base_url: str = "https://baldes.laioseman.com/") -> int:
    source, output, root = source.resolve(), output.resolve(), root.resolve()
    if source == output or source in output.parents or output in source.parents:
        raise ValueError("Source and output directories must be separate, not nested.")
    if output.exists() and any(output.iterdir()):
        marker = output / ".generated-docs"
        if not marker.is_file() or marker.read_text() != MARKER:
            raise ValueError(f"Refusing to replace non-generated directory: {output}")
    md = parser()
    pages = page_order(read_pages(source, md))
    lookup = {p.source: p for p in pages}
    assets: dict[Path, Path] = {}
    search = [entry for page in pages for entry in search_entries(page)]
    for page in pages:
        rewrite_tokens(page, lookup, root, repository.rstrip("/"), assets)
    # Render and validate before replacing the previous generated build.
    rendered = [(page, render_shell(page, pages, md.renderer.render(page.tokens, md.options, {}), repository.rstrip("/"), base_url)) for page in pages]
    output.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix=".docs-build-", dir=output.parent) as temporary:
        stage = Path(temporary) / "docs"
        static = stage / "_static"
        static.mkdir(parents=True)
        for name, destination in [("style.css", "site.css"), ("docs.css", "docs.css"), ("docs.js", "docs.js"), ("app.js", "app.js"), ("mark.svg", "mark.svg")]:
            shutil.copy2(ROOT / "landing" / name, static / destination)
        (static / "syntax.css").write_text(HtmlFormatter(style=LandingDarkStyle).get_style_defs(".prose pre"), encoding="utf-8")
        for page, document in rendered:
            destination = stage / page.output
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(document + "\n", encoding="utf-8")
        for destination, original in assets.items():
            target = stage / destination
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(original, target)
        (stage / "search-index.json").write_text(json.dumps(search, ensure_ascii=False), encoding="utf-8")
        (stage / ".generated-docs").write_text(MARKER, encoding="utf-8")
        old = Path(temporary) / "previous"
        if output.exists():
            output.rename(old)
        try:
            stage.rename(output)
        except OSError:
            if old.exists():
                old.rename(output)
            raise
    return len(pages)


def main() -> int:
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("--source", type=Path, default=ROOT / "docs")
    cli.add_argument("--output", type=Path, default=ROOT / "landing" / "docs")
    cli.add_argument("--repository-url", default="https://github.com/lseman/baldes")
    cli.add_argument("--base-url", default="https://baldes.laioseman.com/", help="Public site URL, including any path prefix")
    args = cli.parse_args()
    try:
        count = build(args.source, args.output, repository=args.repository_url, base_url=args.base_url)
    except (OSError, ValueError) as error:
        print(f"Documentation build failed: {error}", file=sys.stderr)
        return 1
    print(f"Compiled {count} guides → {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
